/**
 * Local FLORENCESS catalogue.
 *
 * The data file is generated by tools/florencess-ref (see PIPELINE.md): every
 * product here was captured from the reference storefront, including its
 * gallery assets. Display prices are strings copied from the reference and are
 * NOT trading amounts — cart/checkout always price through Medusa variants (see
 * florencess-variants.ts). A product without a mapped variant cannot be added
 * to the cart.
 */
import catalogJson from "@/data/florencess-catalog.json";

export type FlOptionValue = { value: string; label: string };
export type FlOption = { id: string; name: string; values: FlOptionValue[] };
export type FlImage = { src: string; alt: string };

export type FlProduct = {
  id: string;
  slug: string;
  title: string;
  model: string;
  brand: string;
  description: string;
  /** Display string exactly as the reference renders it, e.g. "$9.99". */
  price: string;
  oldPrice: string;
  discount: string;
  currency: string;
  availability: string;
  options: FlOption[];
  localImages: FlImage[];
  pageCaptured: boolean;
};

export type FlCategory = {
  slug: string;
  title: string;
  sourceTotal: number | null;
  pageCount: number;
  pagesCaptured: number;
  captured: number;
  empty: boolean;
  productIds: string[];
};

type FlCatalogFile = {
  generatedAt: string;
  source: string;
  snapshot: {
    scope: string;
    categoryPages: number;
    products: number;
    productPagesCaptured: number;
    productPagesMissing: number;
    images: number;
    imagesMissing?: number;
    assetFailures?: number;
  };
  categories: FlCategory[];
  products: FlProduct[];
};

export const FL_CATALOG = catalogJson as unknown as FlCatalogFile;

const productById = new Map<string, FlProduct>();
const productBySlug = new Map<string, FlProduct>();
for (const product of FL_CATALOG.products) {
  productById.set(product.id, product);
  productBySlug.set(product.slug, product);
}

const categoryBySlug = new Map<string, FlCategory>();
for (const category of FL_CATALOG.categories) {
  categoryBySlug.set(category.slug, category);
}

/** Category slugs in the reference's menu order. */
export const FL_CATEGORY_SLUGS = FL_CATALOG.categories.map((category) => category.slug);
export const FL_PRODUCT_SLUGS = FL_CATALOG.products.map((product) => product.slug);

export function getFlCategory(slug: string): FlCategory | undefined {
  return categoryBySlug.get(slug);
}

export function getFlProduct(slug: string): FlProduct | undefined {
  return productBySlug.get(slug);
}

export function getFlProductById(id: string): FlProduct | undefined {
  return productById.get(id);
}

/** Products of one category, in the reference capture order. */
export function flCategoryProducts(category: FlCategory): FlProduct[] {
  const list: FlProduct[] = [];
  for (const id of category.productIds) {
    const product = productById.get(id);
    if (product) list.push(product);
  }
  return list;
}

/** Categories a product belongs to, in menu order. */
export function flProductCategories(product: FlProduct): FlCategory[] {
  return FL_CATALOG.categories.filter((category) => category.productIds.includes(product.id));
}

/** Same-category recommendations that resolve to a real local detail page. */
export function flRelatedProducts(product: FlProduct, limit = 8): FlProduct[] {
  const [primary] = flProductCategories(product);
  if (!primary) return [];
  const related: FlProduct[] = [];
  for (const id of primary.productIds) {
    if (id === product.id) continue;
    const candidate = productById.get(id);
    if (!candidate || !candidate.localImages.length) continue;
    related.push(candidate);
    if (related.length >= limit) break;
  }
  return related;
}

function numericPrice(product: FlProduct): number | null {
  const match = product.price.replaceAll(",", "").match(/[0-9]+(?:\.[0-9]+)?/);
  return match ? Number(match[0]) : null;
}

export { numericPrice as flNumericPrice };

/** Only products with a verifiable current price below the displayed former price. */
export function flHasVerifiedDiscount(product: FlProduct): boolean {
  const current = numericPrice(product);
  const former = product.oldPrice.replaceAll(",", "").match(/[0-9]+(?:\.[0-9]+)?/);
  const old = former ? Number(former[0]) : null;
  return current !== null && old !== null && current > 0 && old > current;
}

export function flDiscountedProducts(): FlProduct[] {
  return FL_CATALOG.products.filter(flHasVerifiedDiscount);
}

export type FlSearchOptions = {
  /** "All Categories" or a category slug; the reference sends category_id. */
  category?: string;
  /** When true the query also matches the description (reference checkbox). */
  includeDescription?: boolean;
  limit?: number;
};

/**
 * Keyword search over the local catalogue. Matching is case-insensitive and
 * requires every whitespace-separated term to appear in the title, model, brand
 * or (optionally) the description. Order follows the catalogue capture order so
 * results are stable across requests.
 */
export function flSearchProducts(query: string, options: FlSearchOptions = {}): FlProduct[] {
  const terms = query
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 8);
  if (!terms.length) return [];

  const pool = options.category
    ? flCategoryProducts(getFlCategory(options.category) ?? { productIds: [] } as unknown as FlCategory)
    : FL_CATALOG.products;

  const matches = pool.filter((product) => {
    const haystack = [
      product.title,
      product.model,
      product.brand,
      options.includeDescription ? product.description : "",
    ]
      .join(" ")
      .toLowerCase();
    return terms.every((term) => haystack.includes(term));
  });
  return options.limit ? matches.slice(0, options.limit) : matches;
}
